    window.LORDRAN_300_DATABASE = LORDRAN_300_DATABASE;

    class Compendium300System {
        constructor(game) {
            this.game = game;
            this.scene = game ? game.scene : null;
            this.spawnedEntities = [];
            this.activeCategory = 'ALL';
            this.searchQuery = '';
            this.initMaterials();
        }

        initMaterials() {
            this.metalMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.85, roughness: 0.3 });
            this.goldMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.25 });
            this.steelMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, metalness: 0.9, roughness: 0.2 });
            this.darkMat = new THREE.MeshStandardMaterial({ color: 0x222226, roughness: 0.8 });
            this.clothMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.9 });
            this.skinMat = new THREE.MeshStandardMaterial({ color: 0xb5977c, roughness: 0.8 });
            this.fireMat = new THREE.MeshStandardMaterial({ color: 0xff4500, emissive: 0xff2200, roughness: 0.2 });
            this.magicMat = new THREE.MeshStandardMaterial({ color: 0x33ffee, emissive: 0x11aabb, roughness: 0.2 });
            this.boneMat = new THREE.MeshStandardMaterial({ color: 0xe0dcd0, roughness: 0.75 });
        }

        // Procedurally sculpt any of the 300 models with high fidelity
        buildModel(entry, x = 0, y = 0, z = 0, scale = 1.0) {
            const root = new THREE.Group();
            root.position.set(x, y, z);
            root.scale.set(scale, scale, scale);

            const primaryMat = new THREE.MeshStandardMaterial({
                color: entry.color,
                metalness: entry.category === 'ARMOR' ? 0.8 : 0.3,
                roughness: entry.category === 'ARMOR' ? 0.35 : 0.75
            });
            const secondaryMat = new THREE.MeshStandardMaterial({
                color: entry.alt_color || 0x333333,
                metalness: 0.5,
                roughness: 0.6
            });

            const arch = entry.archetype || 'humanoid_knight';

            if (arch === 'colossal_titan') {
                // Colossal Bulky Frame (Smough, Havel, Giant Sentinel)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.6;
                root.add(bodyGroup);

                const torso = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.8, 1.0), primaryMat);
                torso.castShadow = true;
                bodyGroup.add(torso);

                const head = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.42, 0.65, 8), primaryMat);
                head.position.y = 1.2;
                bodyGroup.add(head);

                // Heavy Arms
                const rArm = new THREE.Mesh(new THREE.BoxGeometry(0.35, 1.2, 0.35), secondaryMat);
                rArm.position.set(0.9, 0.2, 0);
                bodyGroup.add(rArm);
                const lArm = new THREE.Mesh(new THREE.BoxGeometry(0.35, 1.2, 0.35), secondaryMat);
                lArm.position.set(-0.9, 0.2, 0);
                bodyGroup.add(lArm);

                // Heavy Legs
                const rLeg = new THREE.Mesh(new THREE.BoxGeometry(0.4, 1.2, 0.45), secondaryMat);
                rLeg.position.set(0.45, -1.2, 0);
                bodyGroup.add(rLeg);
                const lLeg = new THREE.Mesh(new THREE.BoxGeometry(0.4, 1.2, 0.45), secondaryMat);
                lLeg.position.set(-0.45, -1.2, 0);
                bodyGroup.add(lLeg);

                if (entry.weapon) {
                    const weaponMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 2.8, 8), this.steelMat);
                    weaponMesh.position.set(1.0, 0.4, 0.6);
                    weaponMesh.rotation.x = 0.8;
                    bodyGroup.add(weaponMesh);
                }

            } else if (arch === 'humanoid_caster') {
                // Robed Spellcaster Frame (Logan, Dusk, Sellen, Ranni)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.35;
                root.add(bodyGroup);

                const robe = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.55, 1.5, 8), primaryMat);
                robe.castShadow = true;
                bodyGroup.add(robe);

                const head = new THREE.Mesh(new THREE.SphereGeometry(0.24, 8, 8), this.skinMat);
                head.position.y = 0.95;
                bodyGroup.add(head);

                const hat = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.06, 12), secondaryMat);
                hat.position.set(0, 1.1, 0);
                bodyGroup.add(hat);
                const hatCone = new THREE.Mesh(new THREE.ConeGeometry(0.35, 0.45, 8), secondaryMat);
                hatCone.position.set(0, 1.3, 0);
                bodyGroup.add(hatCone);

                // Staff / Catalyst
                const staff = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 2.2, 6), this.goldMat);
                staff.position.set(0.55, 0.2, 0.4);
                staff.rotation.x = 0.3;
                bodyGroup.add(staff);

                const gem = new THREE.Mesh(new THREE.DodecahedronGeometry(0.18), this.magicMat);
                gem.position.set(0, 1.15, 0);
                staff.add(gem);

            } else if (arch === 'beast_quadruped') {
                // Quadruped Beast Frame (Boar, Dog, Basilisk, Sif minor)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 0.9;
                root.add(bodyGroup);

                const torso = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.8, 1.8), primaryMat);
                torso.castShadow = true;
                bodyGroup.add(torso);

                const head = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.6, 0.8), primaryMat);
                head.position.set(0, 0.4, 1.1);
                bodyGroup.add(head);

                // 4 legs
                [[-0.45, 0.7], [0.45, 0.7], [-0.45, -0.7], [0.45, -0.7]].forEach(([lx, lz]) => {
                    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.9, 6), secondaryMat);
                    leg.position.set(lx, -0.6, lz);
                    bodyGroup.add(leg);
                });

            } else if (arch === 'serpent_slither') {
                // Serpentine Slither Frame (Man-Serpent, Medusa, Cobra)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.1;
                root.add(bodyGroup);

                const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.45, 1.3, 8), primaryMat);
                torso.castShadow = true;
                bodyGroup.add(torso);

                const head = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.4, 0.65), primaryMat);
                head.position.set(0, 0.85, 0.2);
                bodyGroup.add(head);

                // Tail segments
                for (let i = 0; i < 4; i++) {
                    const seg = new THREE.Mesh(new THREE.CylinderGeometry(0.35 - i * 0.06, 0.4 - i * 0.06, 0.7, 6), primaryMat);
                    seg.position.set(Math.sin(i * 0.8) * 0.35, -0.7 - i * 0.3, -i * 0.5);
                    seg.rotation.x = 0.7;
                    bodyGroup.add(seg);
                }

            } else if (arch === 'ethereal_winged') {
                // Winged Demon / Harpy / Ghost Frame
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.5;
                root.add(bodyGroup);

                const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.4, 1.4, 8), primaryMat);
                bodyGroup.add(torso);

                const head = new THREE.Mesh(new THREE.SphereGeometry(0.25, 8, 8), secondaryMat);
                head.position.y = 0.9;
                bodyGroup.add(head);

                // Wings
                const wingL = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.8, 0.04), primaryMat);
                wingL.position.set(-1.1, 0.4, -0.2);
                wingL.rotation.y = 0.35;
                bodyGroup.add(wingL);
                const wingR = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.8, 0.04), primaryMat);
                wingR.position.set(1.1, 0.4, -0.2);
                wingR.rotation.y = -0.35;
                bodyGroup.add(wingR);

            } else if (arch === 'jar_living') {
                // Living Jar Frame (Alexander, Bairn)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.0;
                root.add(bodyGroup);

                const jar = new THREE.Mesh(new THREE.SphereGeometry(0.9, 14, 12), primaryMat);
                jar.scale.set(1.0, 0.9, 1.0);
                bodyGroup.add(jar);

                const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.2, 14), secondaryMat);
                rim.position.y = 0.85;
                bodyGroup.add(rim);

                const seal = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.4, 0.05), this.fireMat);
                seal.position.set(0, 0.4, 0.88);
                bodyGroup.add(seal);

            } else if (arch === 'skeleton_undead') {
                // Skeleton Frame (Bone ribcage, skull)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.25;
                root.add(bodyGroup);

                const ribs = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.22, 1.1, 6), this.boneMat);
                bodyGroup.add(ribs);

                const skull = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 6), this.boneMat);
                skull.position.y = 0.8;
                bodyGroup.add(skull);

                const scimitar = new THREE.Mesh(new THREE.BoxGeometry(0.08, 1.4, 0.02), this.steelMat);
                scimitar.position.set(0.45, 0.2, 0.4);
                bodyGroup.add(scimitar);

            } else {
                // Standard Humanoid Knight Frame (Artorias, Elite Knight, Solaire, etc.)
                const bodyGroup = new THREE.Group();
                bodyGroup.position.y = 1.35;
                root.add(bodyGroup);

                const torso = new THREE.Mesh(new THREE.BoxGeometry(0.75, 1.3, 0.45), primaryMat);
                torso.castShadow = true;
                bodyGroup.add(torso);

                const helm = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.26, 0.45, 8), primaryMat);
                helm.position.y = 0.88;
                bodyGroup.add(helm);

                // Arms
                const rArm = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.9, 0.2), secondaryMat);
                rArm.position.set(0.5, 0.15, 0);
                bodyGroup.add(rArm);
                const lArm = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.9, 0.2), secondaryMat);
                lArm.position.set(-0.5, 0.15, 0);
                bodyGroup.add(lArm);

                // Legs
                const rLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.9, 0.22), secondaryMat);
                rLeg.position.set(0.22, -0.9, 0);
                bodyGroup.add(rLeg);
                const lLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.9, 0.22), secondaryMat);
                lLeg.position.set(-0.22, -0.9, 0);
                bodyGroup.add(lLeg);

                // Weapon
                const sword = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.8, 0.04), this.steelMat);
                sword.position.set(0.6, 0.3, 0.5);
                sword.rotation.x = 0.8;
                bodyGroup.add(sword);

                // Shield
                if (entry.shield) {
                    const shield = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.3, 0.8), primaryMat);
                    shield.position.set(-0.6, 0.1, 0.3);
                    bodyGroup.add(shield);
                }
            }

            // Dynamic PointLight for radiant visual feedback
            const auraColor = (entry.category === 'ARMOR') ? 0xd4af37 : (entry.category === 'NPC' ? 0x00ffaa : 0xff3300);
            const auraLight = new THREE.PointLight(auraColor, 1.8, 6.0);
            auraLight.position.set(0, 1.2, 0.4);
            root.add(auraLight);

            root.userData = { entry, isCompendiumEntity: true };
            return root;
        }

        // Spawn a 3D model right in front of the player
        spawnInWorld(entryId) {
            const entry = LORDRAN_300_DATABASE.find(e => e.id === entryId);
            if (!entry) return;

            let px = 0, py = 0, pz = 10;
            if (this.game && this.game.playerMesh) {
                const pPos = this.game.playerMesh.position;
                const pRot = this.game.playerMesh.rotation.y;
                px = pPos.x + Math.sin(pRot) * 3.5;
                pz = pPos.z + Math.cos(pRot) * 3.5;
                py = this.game.world ? this.game.world.getGroundHeight(px, pz) : pPos.y;
            }

            const modelMesh = this.buildModel(entry, px, py, pz, 1.0);
            modelMesh.userData = {
                entry: entry,
                isSpawned3D: true,
                hp: entry.hp || 150,
                maxHp: entry.hp || 150
            };
            if (this.scene) {
                this.scene.add(modelMesh);
                this.spawnedEntities.push(modelMesh);
            }

            if (this.game && this.game.showNotification) {
                this.game.showNotification(`📦 3D MODEL SPAWNED: ${entry.name}`);
            }
            if (window.dsAudio && window.dsAudio.playBonfireIgnite) {
                window.dsAudio.playBonfireIgnite();
            }
            return modelMesh;
        }

        // Equip armor directly
        equipArmor(entryId) {
            const entry = LORDRAN_300_DATABASE.find(e => e.id === entryId);
            if (!entry || entry.category !== 'ARMOR') return;

            if (this.game && this.game.combat) {
                this.game.combat.equippedSkin = entry.raw_id || 'elite_knight';
                localStorage.setItem('darksouls_equipped_skin', entry.raw_id || 'elite_knight');
            }
            if (this.game && this.game.characters && this.game.characters.equipSkin) {
                this.game.characters.equipSkin(this.game.playerMesh, entry.raw_id || 'elite_knight');
            }
            if (this.game && this.game.showNotification) {
                this.game.showNotification(`🛡️ ARMOR EQUIPPED: ${entry.name} • ${entry.stat}`);
            }
            if (window.dsAudio && window.dsAudio.playRoll) {
                window.dsAudio.playRoll();
            }
        }

        // Summon companion NPC with Golden Phantom shimmer & combat AI
        summonNPC(entryId) {
            const entry = LORDRAN_300_DATABASE.find(e => e.id === entryId);
            if (!entry || entry.category !== 'NPC') return;
            
            let px = 0, py = 0, pz = 10;
            if (this.game && this.game.playerMesh) {
                const pPos = this.game.playerMesh.position;
                const pRot = this.game.playerMesh.rotation.y;
                px = pPos.x + Math.sin(pRot) * 2.8;
                pz = pPos.z + Math.cos(pRot) * 2.8;
                py = this.game.world ? this.game.world.getGroundHeight(px, pz) : pPos.y;
            }

            const modelMesh = this.buildModel(entry, px, py, pz, 1.0);
            
            // Golden phantom companion aura & light
            const phantomAura = new THREE.PointLight(0xffd700, 2.5, 8.0);
            phantomAura.position.set(0, 1.5, 0);
            modelMesh.add(phantomAura);
            
            modelMesh.userData = {
                entry: entry,
                isSpawned3D: true,
                isSummonedAlly: true,
                hp: entry.hp || 500,
                maxHp: entry.hp || 500,
                damage: 75,
                attackCooldown: 0,
                animTime: 0
            };

            if (this.scene) {
                this.scene.add(modelMesh);
                this.spawnedEntities.push(modelMesh);
            }

            if (this.game && this.game.showNotification) {
                this.game.showNotification(`🧙 GOLDEN ALLY SUMMONED: ${entry.name}`);
                this.game.showNotification(`💬 "${entry.quote}"`);
            }
            if (this.game && this.game.audio && this.game.audio.playBellToll) {
                this.game.audio.playBellToll();
            } else if (window.dsAudio && window.dsAudio.playBonfireIgnite) {
                window.dsAudio.playBonfireIgnite();
            }
            return modelMesh;
        }

        // Banish all summoned companion allies
        dismissAllCompanions() {
            let count = 0;
            for (let i = this.spawnedEntities.length - 1; i >= 0; i--) {
                const ent = this.spawnedEntities[i];
                if (ent && (ent.userData.isSummonedAlly || (ent.userData.entry && ent.userData.entry.category === 'NPC'))) {
                    if (ent.parent) ent.parent.remove(ent);
                    else if (this.scene) this.scene.remove(ent);
                    this.spawnedEntities.splice(i, 1);
                    count++;
                }
            }
            if (this.game && this.game.showNotification) {
                this.game.showNotification(`✨ ${count} NPC SUMMONS BANISHED TO THEIR REALMS`);
            }
            if (this.game && this.game.audio && this.game.audio.playRoll) {
                this.game.audio.playRoll();
            }
        }

        // Challenge mob
        challengeMob(entryId) {
            const entry = LORDRAN_300_DATABASE.find(e => e.id === entryId);
            if (!entry || entry.category !== 'MOB') return;
            const mesh = this.spawnInWorld(entryId);
            if (this.game && this.game.combat && mesh) {
                const mobEntity = {
                    id: entry.id,
                    name: entry.name,
                    mesh: mesh,
                    hp: entry.hp || 300,
                    maxHp: entry.hp || 300,
                    damage: entry.dmg || 60,
                    souls: entry.souls || 200,
                    speed: 2.8,
                    attackReach: 2.5,
                    isDead: false,
                    isStaggered: false,
                    staggerTimer: 0,
                    state: 'CHASE',
                    behaviorType: 'Swarm',
                    animTime: 0,
                    cooldown: 1.0,
                    attackTime: 0
                };
                if (!this.game.combat.enemies) this.game.combat.enemies = [];
                this.game.combat.enemies.push(mobEntity);
            }
            if (this.game && this.game.showNotification) {
                this.game.showNotification(`⚔️ MOB CHALLENGE ENGAGED: ${entry.name} • HP: ${entry.hp}`);
            }
        }

        // Companion AI Update loop (Follow player, attack hostile bosses/mobs, defend)
        update(delta) {
            if (!this.spawnedEntities || this.spawnedEntities.length === 0) return;
            const player = this.game ? this.game.playerMesh : null;
            if (!player) return;
            const pPos = player.position;

            // Find nearest active hostile target
            let targetEnemy = null;
            let minDist = 30.0;

            if (this.game.combat && this.game.combat.boss && !this.game.combat.boss.isDead && this.game.combat.boss.state !== 'IDLE') {
                const bMesh = this.game.combat.boss.mesh;
                if (bMesh) {
                    const d = pPos.distanceTo(bMesh.position);
                    if (d < minDist) {
                        targetEnemy = { mesh: bMesh, hpObj: this.game.combat.boss, isBoss: true };
                        minDist = d;
                    }
                }
            }

            if (!targetEnemy && this.game.combat && this.game.combat.enemies) {
                for (const em of this.game.combat.enemies) {
                    if (em && !em.isDead && em.mesh && em.mesh.parent) {
                        const d = pPos.distanceTo(em.mesh.position);
                        if (d < minDist) {
                            targetEnemy = { mesh: em.mesh, hpObj: em, isBoss: false };
                            minDist = d;
                        }
                    }
                }
            }

            for (const ent of this.spawnedEntities) {
                if (!ent || !ent.parent || !ent.userData.isSummonedAlly) continue;
                ent.userData.animTime = (ent.userData.animTime || 0) + delta;
                ent.userData.attackCooldown = Math.max(0, (ent.userData.attackCooldown || 0) - delta);

                const pos = ent.position;

                if (targetEnemy && targetEnemy.mesh) {
                    // Attack active enemy
                    const ePos = targetEnemy.mesh.position;
                    const toEnemy = new THREE.Vector3(ePos.x - pos.x, 0, ePos.z - pos.z);
                    const distToE = toEnemy.length();

                    if (distToE > 2.4) {
                        toEnemy.normalize();
                        pos.x += toEnemy.x * delta * 3.5;
                        pos.z += toEnemy.z * delta * 3.5;
                        ent.rotation.y = Math.atan2(toEnemy.x, toEnemy.z);
                        pos.y = (this.game.world ? this.game.world.getGroundHeight(pos.x, pos.z, pos.y) : pos.y) + Math.abs(Math.sin(ent.userData.animTime * 10)) * 0.08;
                    } else {
                        // In attack reach: swing at enemy
                        ent.rotation.y = Math.atan2(toEnemy.x, toEnemy.z);
                        if (ent.userData.attackCooldown <= 0) {
                            ent.userData.attackCooldown = 1.3;
                            const dmg = Math.floor(ent.userData.damage * (0.85 + Math.random() * 0.3));
                            if (targetEnemy.isBoss) {
                                targetEnemy.hpObj.hp -= dmg;
                                if (this.game.combat.showBossDamage) this.game.combat.showBossDamage(dmg);
                            } else {
                                targetEnemy.hpObj.hp -= dmg;
                                if (targetEnemy.hpObj.hp <= 0) {
                                    targetEnemy.hpObj.isDead = true;
                                    if (targetEnemy.mesh.parent) targetEnemy.mesh.parent.remove(targetEnemy.mesh);
                                }
                            }
                            if (this.game.showDamageNumber) this.game.showDamageNumber(ePos, dmg, false);
                            if (this.game.world && this.game.world.spawnHitSparks) this.game.world.spawnHitSparks(ePos, false);
                            if (this.game.audio && this.game.audio.playHit) this.game.audio.playHit(false);
                            
                            // Visual weapon lunge
                            ent.position.y += 0.12;
                            setTimeout(() => { if (ent && ent.parent) ent.position.y -= 0.12; }, 180);
                        }
                    }
                } else {
                    // No enemy: follow player smoothly
                    const toPlayer = new THREE.Vector3(pPos.x - pos.x, 0, pPos.z - pos.z);
                    const distToP = toPlayer.length();

                    if (distToP > 4.2) {
                        toPlayer.normalize();
                        const speed = distToP > 8.0 ? 5.2 : 3.2;
                        pos.x += toPlayer.x * delta * speed;
                        pos.z += toPlayer.z * delta * speed;
                        ent.rotation.y = Math.atan2(toPlayer.x, toPlayer.z);
                        pos.y = (this.game.world ? this.game.world.getGroundHeight(pos.x, pos.z, pos.y) : pos.y) + Math.abs(Math.sin(ent.userData.animTime * 9)) * 0.06;
                    } else if (distToP < 2.0) {
                        toPlayer.normalize();
                        pos.x -= toPlayer.x * delta * 1.5;
                        pos.z -= toPlayer.z * delta * 1.5;
                    } else {
                        ent.rotation.y = Math.atan2(toPlayer.x, toPlayer.z);
                        const groundY = this.game.world ? this.game.world.getGroundHeight(pos.x, pos.z, pos.y) : 0;
                        pos.y = groundY + Math.sin(ent.userData.animTime * 2) * 0.02;
                    }
                }
            }
        }

        // Clear all spawned entities
        clearSpawned() {
            this.spawnedEntities.forEach(e => {
                if (e.parent) e.parent.remove(e);
                else if (this.scene) this.scene.remove(e);
            });
            this.spawnedEntities = [];
            if (this.game && this.game.combat && this.game.combat.enemies) {
                this.game.combat.enemies = this.game.combat.enemies.filter(e => e.mesh && e.mesh.parent);
            }
            if (this.game && this.game.showNotification) {
                this.game.showNotification(`🧹 ALL SPAWNED 3D ENTITIES CLEARED`);
            }
        }
    }

    window.LordranCompendium300 = Compendium300System;

    // Helper UI render functions
    window.openCompendiumModal = function() {
        const modal = document.getElementById('compendium-300-modal');
        if (!modal) return;
        modal.style.display = 'flex';
        renderCompendiumCards();
    };

    window.closeCompendiumModal = function() {
        const modal = document.getElementById('compendium-300-modal');
        if (modal) modal.style.display = 'none';
    };

    window.filterCompendiumCategory = function(cat) {
        window.activeCompendiumCategory = cat;
        document.querySelectorAll('.compendium-tab-btn').forEach(btn => {
            btn.classList.toggle('active', btn.getAttribute('data-category') === cat);
        });
        renderCompendiumCards();
    };

    window.onCompendiumSearchInput = function(query) {
        window.compendiumSearchQuery = (query || '').toLowerCase().trim();
        renderCompendiumCards();
    };

    function renderCompendiumCards() {
        const grid = document.getElementById('compendium-cards-grid');
        if (!grid || !window.LORDRAN_300_DATABASE) return;

        const cat = window.activeCompendiumCategory || 'ALL';
        const q = window.compendiumSearchQuery || '';

        const filtered = window.LORDRAN_300_DATABASE.filter(item => {
            const matchCat = (cat === 'ALL' || item.category === cat);
            const matchQuery = !q || item.name.toLowerCase().includes(q) || item.desc.toLowerCase().includes(q) || item.title.toLowerCase().includes(q);
            return matchCat && matchQuery;
        });

        grid.innerHTML = filtered.map(item => {
            const catBadgeColor = item.category === 'ARMOR' ? '#ffd700' : (item.category === 'NPC' ? '#00ffaa' : '#ff5555');
            const catBadgeBg = item.category === 'ARMOR' ? 'rgba(212,175,55,0.15)' : (item.category === 'NPC' ? 'rgba(0,255,170,0.15)' : 'rgba(255,85,85,0.15)');

            let actionBtn = '';
            if (item.category === 'ARMOR') {
                actionBtn = `<button class="btn-fight-boss" onclick="window.compendiumInstance.equipArmor('${item.id}')" style="border-color: #ffd700; color: #fff3a8; padding: 6px 10px; font-size: 0.72rem; margin-right: 4px;">🛡️ EQUIP</button>`;
            } else if (item.category === 'NPC') {
                actionBtn = `<button class="btn-fight-boss" onclick="window.compendiumInstance.summonNPC('${item.id}')" style="border-color: #00ffaa; color: #a5ffbe; padding: 6px 10px; font-size: 0.72rem; margin-right: 4px;">🧙 SUMMON</button>`;
            } else {
                actionBtn = `<button class="btn-fight-boss" onclick="window.compendiumInstance.challengeMob('${item.id}')" style="border-color: #ff5555; color: #ffaaaa; padding: 6px 10px; font-size: 0.72rem; margin-right: 4px;">⚔️ FIGHT</button>`;
            }

            return `
                <div class="boss-card" style="border-color: rgba(255,255,255,0.12); padding: 10px;">
                    <div class="boss-card-info" style="gap: 12px;">
                        <div class="boss-card-icon" style="font-size: 1.8rem;">${item.icon}</div>
                        <div class="boss-card-text">
                            <div style="display: flex; align-items: center; gap: 8px;">
                                <span style="font-size: 0.65rem; font-weight: 800; padding: 2px 6px; border-radius: 3px; border: 1px solid ${catBadgeColor}; color: ${catBadgeColor}; background: ${catBadgeBg};">${item.category}</span>
                                <div class="boss-card-name" style="font-size: 0.88rem;">${item.name}</div>
                            </div>
                            <div class="boss-card-desc" style="font-size: 0.75rem; color: #b8b0a2; margin-top: 2px;">${item.desc}</div>
                            <div class="boss-card-stats" style="font-size: 0.72rem; color: #ffd778; margin-top: 3px;">${item.title}</div>
                        </div>
                    </div>
                    <div style="display: flex; gap: 6px; margin-top: 8px; justify-content: flex-end;">
                        ${actionBtn}
                        <button class="btn-fight-boss" onclick="window.compendiumInstance.spawnInWorld('${item.id}')" style="padding: 6px 10px; font-size: 0.72rem; border-color: #64b5f6; color: #bbdefb; background: rgba(20,40,70,0.5);">📦 SPAWN 3D</button>
                    </div>
                </div>
            `;
        }).join('');
    }


